test('permits Count values from 0 through 3 inclusive', () => {
  assert.equal(permit(0), true);
  assert.equal(permit(3), true);
});

test('rejects boundary values outside the permitted range', () => {
  assert.equal(permit(-1), false);
  assert.equal(permit(4), false);
});

test('rejects malformed inputs without coercion', () => {
  for (const input of ['1', null, undefined, NaN, Infinity, -Infinity, 1.5]) {
    assert.equal(permit(input), false);
  }
});

